const { vars } = resolveWorkspaceIdentity({ cwd: CWD, cache: false });
const PEER = vars.git_remote;
const SID = `dsh-sim-product20-${Date.now()}`;

function headers(extra = {}) {
  return {
    "Content-Type": "application/json",
    "X-OpenViking-Account": "default",
    "X-OpenViking-User": "default",
    "X-OpenViking-Actor-Peer": PEER,
    ...extra,
  };
}

async function api(path, init = {}, { actor = true } = {}) {
  const h = { ...(init.headers || {}) };
  if (!actor) delete h["X-OpenViking-Actor-Peer"];
  const r = await fetch(API + path, { ...init, headers: { ...headers(), ...h } });
  const t = await r.text();
  let j;
  try {
    j = JSON.parse(t);
  } catch {
    throw new Error(`${path} ${r.status} non-json: ${t.slice(0, 200)}`);
  }
  if (!r.ok) throw new Error(`${path} ${r.status} ${JSON.stringify(j).slice(0, 300)}`);
  return j;
}

function turns() {
  const marker = `OV_SIM_TEST_${SID.slice(-8)}`;
  const base = [
    {
      role: "user",
      message_kind: "user_query",
      content:
        `禅道 6033（模拟）产品2.0 zhi2-web-admin：maintenance/initiation/detail.vue 里 zs-dialog 的 #append 误嵌在 #prepend 内，保存后 footer 错位。${marker}`,
    },
    {
      role: "assistant",
      message_kind: "assistant_response",
      content:
        `先 grep slot 结构，对比 maintenance/maintenanceProject/detail.vue 已修模式：#title/#footer 与 #prepend 同级。标记 ${marker}`,
    },
    {
      role: "user",
      message_kind: "user_query",
      content: "按 11/05 那批 Vue 插槽修复先例改，改完 npm run build 走 nginx UI 验证。",
    },
    {
      role: "assistant",
      message_kind: "assistant_response",
      content:
        "已将 #append 移到与 #prepend 同级；build 通过。根因：template 插槽嵌套导致 footer 渲染到 prepend 区域。",
    },
  ];
  // 拉长上下文，逼近插件 8000 阈值场景（多轮 user/assistant）
  const pad =
    "涉及文件 zhi2-web-admin/src/views/maintenance/initiation/detail.vue；项目产品2.0；请用简体中文写入记忆。 ";
  const out = [];
  for (let i = 0; i < 6; i++) {
    for (const m of base) {
      out.push({ ...m, content: m.content + " " + pad.repeat(3) + `(轮次${i + 1})` });
    }
  }
  return { msgs: out, marker };
}

function classifyEntries(entries) {
  const stats = { peerProduct: 0, peerOther: 0, userGlobal: 0, titles: [] };
  for (const e of entries || []) {
    const u = e.uri || "";
    stats.titles.push((e.abstract || e.title || u).slice(0, 60));
    if (u.includes(`/peers/${PEER}`)) stats.peerProduct++;
    else if (u.includes("/peers/")) stats.peerOther++;
    else stats.userGlobal++;
  }
  return stats;
}

async function search(query, peerScope, useActorHeader) {
  const h = useActorHeader ? headers() : { ...headers(), "X-OpenViking-Actor-Peer": "" };
  delete h["X-OpenViking-Actor-Peer"];
  if (useActorHeader) h["X-OpenViking-Actor-Peer"] = PEER;
  const r = await fetch(`${API}/api/v1/search/search`, {
    method: "POST",
    headers: h,
    body: JSON.stringify({
      query,
      mode: "context",
      purpose: "coding",
      max_tokens: 1200,
      peer_scope: peerScope,
      limit: 10,
    }),
  });
  const j = await r.json();
  const entries = j.result?.entries || j.entries || [];
  return classifyEntries(entries);
}

async function pollTask(tid, max = 120) {
  for (let k = 0; k < max; k++) {
    await new Promise((r) => setTimeout(r, 5000));
    const j = await api(`/api/v1/tasks/${tid}`, {}, { actor: true });
    const list = Array.isArray(j.result) ? j.result : [j.result || j];
    const t = list.find((x) => x?.task_id === tid) || list[0] || {};
    if (["completed", "failed", "error", "cancelled"].includes(t.status)) return t;
  }
  throw new Error("task timeout");
}

async function main() {
  console.log(JSON.stringify({ step: "init", peer: PEER, session: SID, cwd: CWD }, null, 2));

  await api("/api/v1/sessions", {
    method: "POST",
    body: JSON.stringify({ session_id: SID }),
  });

  const { msgs, marker } = turns();
  const approxChars = msgs.reduce((s, m) => s + m.content.length, 0);
  console.log(JSON.stringify({ step: "messages", count: msgs.length, approxChars }, null, 2));

  await api(`/api/v1/sessions/${encodeURIComponent(SID)}/messages/batch`, {
    method: "POST",
    body: JSON.stringify({ messages: msgs }),
  });

  const before = {
    actor: await search("maintenance detail.vue append prepend 插槽", "actor", true),
    all: await search("maintenance detail.vue append prepend 插槽", "all", true),
  };
  console.log(JSON.stringify({ step: "recall_before_commit", before }, null, 2));

  const c = await api(`/api/v1/sessions/${encodeURIComponent(SID)}/commit`, {
    method: "POST",
    body: JSON.stringify({}),
  });
  const tid = c.result?.task_id;
  console.log(JSON.stringify({ step: "commit_started", task_id: tid }, null, 2));
  const task = await pollTask(tid);
  const ex = task.result?.memories_extracted || {};
  console.log(
    JSON.stringify(
      {
        step: "commit_done",
        status: task.status,
        extracted: ex,
        tokens: task.result?.token_usage?.total?.total_tokens,
        secs: task.processing_seconds,
      },
      null,
      2
    )
  );

  const metaPath = path.join(
    os.homedir(),
    ".openviking/data/viking/default/user/default/sessions",
    SID,
    ".meta.json"
  );
  let meta = null;
  if (fs.existsSync(metaPath)) meta = JSON.parse(fs.readFileSync(metaPath, "utf8"));

  const after = {
    actor: await search(`OV_SIM ${marker} 6033 插槽`, "actor", true),
    all: await search(`OV_SIM ${marker} 6033 插槽`, "all", true),
  };

  const report = {
    ok: task.status === "completed" && ((ex.memory_write || 0) + (ex.memory_edit || 0) > 0),
    peer: PEER,
    session: SID,
    marker,
    meta: meta
      ? {
          pending: meta.pending_tokens,
          extracted: meta.memories_extracted?.total,
          commits: meta.commit_count,
        }
      : null,
    recall_before: before,
    recall_after: after,
    actor_reduces_other_peers:
      before.actor.peerOther <= before.all.peerOther &&
      after.actor.peerOther <= after.all.peerOther,
  };
  console.log("\n=== REPORT ===");
  console.log(JSON.stringify(report, null, 2));
  process.exit(report.ok ? 0 : 1);
}

main().catch((e) => {
  console.error(e);
  process.exit(1);
});

